//! Hunspell dictionaries from a pinned commit of `wooorm/dictionaries`
//! (ZapZap downloads Qt `.bdic` files instead). The catalog is embedded and
//! regenerated by `scripts/hunspell-catalog.mjs`; every file is verified
//! against its git blob SHA-1 and size.

use std::sync::OnceLock;

use serde::Deserialize;
use sha1::{Digest, Sha1};

const CATALOG_JSON: &str = include_str!("../../resources/hunspell-catalog.json");

#[derive(Debug, Deserialize)]
pub struct Catalog {
    pub repository: String,
    pub commit: String,
    pub dictionaries: Vec<Entry>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Entry {
    /// Code in the repository, e.g. `pt-PT`.
    pub code: String,
    pub aff: Blob,
    pub dic: Blob,
}

#[derive(Debug, Clone, Deserialize)]
pub struct Blob {
    pub sha: String,
    pub size: u64,
}

pub fn catalog() -> &'static Catalog {
    static CATALOG: OnceLock<Catalog> = OnceLock::new();
    CATALOG.get_or_init(|| serde_json::from_str(CATALOG_JSON).expect("valid embedded catalog"))
}

impl Catalog {
    pub fn find(&self, tag: &str) -> Option<&Entry> {
        self.dictionaries.iter().find(|e| e.tag() == tag)
    }

    pub fn file_url(&self, entry: &Entry, ext: &str) -> String {
        format!(
            "https://raw.githubusercontent.com/{}/{}/dictionaries/{}/index.{ext}",
            self.repository, self.commit, entry.code
        )
    }
}

impl Entry {
    /// The Enchant tag the dictionary is installed and requested under.
    pub fn tag(&self) -> String {
        enchant_tag(&self.code)
    }
}

/// Enchant's tag normalization: the first `-` becomes `_`, the language is
/// lower case and everything after it upper case (`pt-PT` → `pt_PT`).
pub fn enchant_tag(code: &str) -> String {
    let code = code.trim();
    let code = code.split(['@', '.']).next().unwrap_or(code);
    let code = code.replacen('-', "_", 1);
    match code.split_once('_') {
        Some((lang, rest)) => format!(
            "{}_{}",
            lang.to_ascii_lowercase(),
            rest.to_ascii_uppercase()
        ),
        None => code.to_ascii_lowercase(),
    }
}

/// Git's blob object id: SHA-1 of `"blob <size>\0" + content`.
pub fn git_blob_sha1(content: &[u8]) -> String {
    let mut hasher = Sha1::new();
    hasher.update(format!("blob {}\0", content.len()).as_bytes());
    hasher.update(content);
    hex::encode(hasher.finalize())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_catalog_is_pinned_and_complete() {
        let c = catalog();
        assert_eq!(c.repository, "wooorm/dictionaries");
        assert_eq!(c.commit.len(), 40);
        assert!(c.dictionaries.len() > 50);
        let pt = c.find("pt_PT").unwrap();
        assert_eq!(pt.code, "pt-PT");
        assert!(c.find("en").is_some());
        for e in &c.dictionaries {
            assert_eq!(e.aff.sha.len(), 40);
            assert!(e.aff.size > 0 && e.dic.size > 0);
        }
        assert!(
            c.file_url(pt, "dic")
                .ends_with("/dictionaries/pt-PT/index.dic")
        );
    }

    #[test]
    fn tags_follow_enchant_normalization() {
        assert_eq!(enchant_tag("pt-PT"), "pt_PT");
        assert_eq!(enchant_tag("en_us.UTF-8"), "en_US");
        assert_eq!(enchant_tag("ca-valencia"), "ca_VALENCIA");
        assert_eq!(enchant_tag("DE"), "de");
        assert_eq!(enchant_tag("sr-Latn"), "sr_LATN");
    }

    #[test]
    fn git_blob_ids_match_git() {
        // `printf 'hello\n' | git hash-object --stdin`
        assert_eq!(
            git_blob_sha1(b"hello\n"),
            "ce013625030ba8dba906f756967f9e9ca394464a"
        );
        assert_eq!(
            git_blob_sha1(b""),
            "e69de29bb2d1d6434b8b29ae775ad8c2e48c5391"
        );
    }
}
